export async function showAutonomy({api,root,esc,allowed,stillCurrent}){
 const data=await api('autonomy');if(!stillCurrent())return;
 const counts=data.counts;
 root.innerHTML=`<section class="autonomy-hero"><span class="eyebrow">AUTONOMY CONTROL</span><h2>Know what PayTrace will do next.</h2><p>PayTrace watches paid purchases, investigates missing access after the delivery window, and can repair only cases inside an enabled merchant policy. Every access write is followed by a fresh verification.</p><div class="metrics"><div class="metric"><strong>${counts.investigate+counts.candidate}</strong><span>Next in queue</span><small>Evidence is refreshed before action</small></div><div class="metric"><strong>${counts.verify+counts.verification}</strong><span>Read-only checks</span><small>No second grant during verification</small></div><div class="metric"><strong>${counts.manual+counts.paused+counts.review}</strong><span>Merchant attention</span><small>Outside policy, paused, or manual</small></div><div class="metric"><strong>${counts.verified}</strong><span>Verified now</span><small>Current proof required</small></div></div></section>
 <section><h2>Operating conditions</h2><div class="autonomy-signals"><span class="pill ${data.readiness.database?'good':'warn'}">Database ${data.readiness.database?'healthy':'check needed'}</span><span class="pill ${data.readiness.worker?'good':'warn'}">Worker ${data.readiness.worker?'active':'waiting'}</span><span class="pill ${data.readiness.connections?'good':'warn'}">Connections ${data.readiness.connections?'ready':'incomplete'}</span><span class="pill ${data.readiness.restoreVerified?'good':'warn'}">Restore probe ${data.readiness.restoreVerified?'passed':'not confirmed'}</span><span class="pill ${data.readiness.workflows?'good':'warn'}">Render ${data.readiness.workflows?'configured':'not configured'}</span></div><p class="notice">${data.readiness.incident?'Shared incident detected: automatic grants pause. ':''}These are live configuration and worker signals, not proof of a completed end-to-end sandbox acceptance test. An unverified access write stays open for read-only checks.</p></section>
 <section><h2>Preview merchant policy</h2><p>Change the values to see how current cases would be classified. This preview never saves a policy, contacts a provider, approves a repair, or writes access.</p><form id="autonomy-sim" class="filters"><label class="check"><input type="checkbox" name="enabled" ${data.policy.enabled?'checked':''}> Simulate enabled policy</label><label>Maximum purchase (USD)<input name="amount" type="number" min="0.01" max="500" step="0.01" value="${(data.policy.maxAmountCents/100).toFixed(2)}" required></label><label>Daily repair limit<input name="limit" type="number" min="1" max="10" value="${data.policy.dailyLimit}" required></label><button>Preview cases</button></form><p id="autonomy-mode" role="status">Showing saved policy · ${data.policy.enabled?'on':'off'}</p><div id="autonomy-cases"></div><p><a class="button" href="focus.html">Open recovery desk to change policy or review a case</a></p></section>`;
 const target=root.querySelector('#autonomy-cases');
 function paint(d){target.innerHTML=d.items.length?`<div class="autonomy-list">${d.items.map(x=>`<article class="autonomy-case"><div class="autonomy-case-body"><span class="pill ${['verified','candidate','verify'].includes(x.status)?'good':['paused','manual','verification'].includes(x.status)?'warn':''}">${esc(x.status.replaceAll('-',' '))}</span><h3>${esc(x.caseId)}</h3><p>${esc(x.reason)}</p><ol class="autonomy-path" aria-label="Recorded recovery progress">${(x.path||[]).map(step=>`<li class="${esc(step.state)}"><span>${esc(step.label)}</span><small>${esc(step.state.replaceAll('-',' '))}</small></li>`).join('')}</ol><small>Next: ${esc(x.next)}</small></div><a class="button" href="focus.html">Open desk</a></article>`).join('')}</div>`:'<p>No cases in this workspace yet. Complete a sandbox purchase to see the automation path.</p>';}
 paint(data);
 root.querySelector('#autonomy-sim').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const form=new FormData(e.target),amount=Math.round(Number(form.get('amount'))*100),limit=Number(form.get('limit'));try{const preview=await api('autonomy?'+new URLSearchParams({simulate:'1',enabled:String(form.has('enabled')),maxAmountCents:String(amount),dailyLimit:String(limit)}));if(!stillCurrent())return;paint(preview);root.querySelector('#autonomy-mode').textContent='Dry run only · no policy or case changed';}catch(error){root.querySelector('#autonomy-mode').textContent=error.message||'Preview unavailable.';}finally{button.disabled=false;}};
}
